<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,AdSet,Ad,SyncRun,RawProviderPayload,CanonicalCreative,CreativeObservation,PerformanceMetric};
use App\Services\Advertising\Sync\{CanonicalCreativeRecorder,AdDataSyncEngine};
use App\Services\Advertising\{OAuthManager,Adapters\MetaAdsAdapter};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\Http;
use Mockery;
use Tests\TestCase;
final class CanonicalCreativeTest extends TestCase {
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Synthetic','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Synthetic','currency'=>'USD']);$s=AdSet::create(['campaign_id'=>$c->id,'external_ad_set_id'=>'set','name'=>'Synthetic']);$ad=Ad::create(['ad_set_id'=>$s->id,'external_ad_id'=>'ad','name'=>'Synthetic']);$run=SyncRun::create(['connected_ad_account_id'=>$a->id,'sync_type'=>'manual','status'=>'completed','started_at'=>now(),'completed_at'=>now()]);$raw=RawProviderPayload::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','endpoint'=>'campaigns','payload'=>[]]);return[$u,$a,$ad,$run,$raw];}
 public function test_exact_provider_identity_reused_across_ads_but_not_accounts_and_history_retained():void{
  [$u,$a,$ad,$run,$raw]=$this->fixture();$rec=new CanonicalCreativeRecorder;$d=['external_creative_id'=>'creative-1','name'=>'Same display name','object_type'=>'VIDEO'];$o=$rec->record($a,$ad,$d,$run,$raw);$again=$rec->record($a,$ad,$d,$run,$raw);$this->assertSame($o->id,$again->id);$ad2=Ad::create(['ad_set_id'=>$ad->ad_set_id,'external_ad_id'=>'ad2','name'=>'Synthetic']);$o2=$rec->record($a,$ad2,$d,$run,$raw);$this->assertSame($o->canonical_creative_id,$o2->canonical_creative_id);
  [$ou,$oa,$oad,$orun,$oraw]=$this->fixture();$foreign=$rec->record($oa,$oad,$d,$orun,$oraw);$this->assertNotSame($o->canonical_creative_id,$foreign->canonical_creative_id);
  $newRun=SyncRun::create(['connected_ad_account_id'=>$a->id,'sync_type'=>'manual','status'=>'failed','started_at'=>now()]);$changed=$d;$changed['external_creative_id']='creative-2';$rec->record($a,$ad,$changed,$newRun,$raw);$this->assertSame(2,CanonicalCreative::where('connected_ad_account_id',$a->id)->count());$this->assertSame(3,CreativeObservation::whereIn('canonical_creative_id',CanonicalCreative::where('connected_ad_account_id',$a->id)->pluck('id'))->count());$this->assertSame(0,PerformanceMetric::where('connected_ad_account_id',$a->id)->count());
  $this->assertLessThan(2,abs($o->fresh()->observed_at->timestamp-time()));
 }
 public function test_conflicts_and_foreign_parent_lineage_rejected():void{[$u,$a,$ad,$run,$raw]=$this->fixture();$rec=new CanonicalCreativeRecorder;$rec->record($a,$ad,['external_creative_id'=>'one'],$run,$raw);foreach([['external_creative_id'=>'two'],['external_creative_id'=>''],['external_creative_id'=>'one','customer_payload'=>[]]]as$d){try{$rec->record($a,$ad,$d,$run,$raw);$this->fail('Invalid/conflicting identity accepted');}catch(\RuntimeException){$this->assertTrue(true);}}[$ou,$oa,$oad]=$this->fixture();try{$rec->record($a,$oad,['external_creative_id'=>'one'],$run,$raw);$this->fail('Foreign ad accepted');}catch(\RuntimeException){$this->assertTrue(true);}}
 public function test_owned_api_cursor_failed_sync_and_corruption_labels():void{[$u,$a,$ad,$run,$raw]=$this->fixture();$o=(new CanonicalCreativeRecorder)->record($a,$ad,['external_creative_id'=>'one','name'=>'Synthetic'],$run,$raw);$base='/api/v1/ad-accounts/'.$a->id.'/canonical-creatives';$this->getJson($base)->assertUnauthorized();$this->actingAs($u,'sanctum')->getJson($base)->assertOk()->assertJsonPath('data.rows.0.recorded_distinct_ads',1)->assertJsonPath('data.provider_verified',false);$url=$base.'/'.$o->canonical_creative_id.'/observations';$this->getJson($url)->assertJsonPath('data.rows.0.integrity_status','recorded_scope_consistent')->assertJsonPath('data.rows.0.sync_status','completed');$run->update(['status'=>'failed']);$this->getJson($url)->assertJsonPath('data.rows.0.sync_status','failed');$o->update(['name'=>'Altered']);$this->getJson($url)->assertJsonPath('data.rows.0.integrity_status','mismatch')->assertJsonMissingPath('data.rows.0.raw_provider_payload_id');$other=User::factory()->create();$this->actingAs($other,'sanctum')->getJson($base)->assertNotFound();$this->getJson($url)->assertNotFound();}
 public function test_meta_fixture_to_shared_sync_preserves_explicit_creative_and_unknown_stays_unknown():void{[$u,$a]=$this->fixture();Http::preventStrayRequests();Http::fake(['graph.facebook.com/*/campaigns*'=>Http::response(['data'=>[['id'=>'new-c','name'=>'Synthetic','status'=>'ACTIVE','adsets'=>['data'=>[['id'=>'new-s','ads'=>['data'=>[['id'=>'with-c','creative'=>['id'=>'shared-c','name'=>'Synthetic','object_type'=>'VIDEO']],['id'=>'unknown-c']]]]]]]]],200),'graph.facebook.com/*/insights*'=>Http::response(['data'=>[]],200)]);$adapter=new MetaAdsAdapter;$manager=Mockery::mock(OAuthManager::class);$manager->shouldReceive('getAdapter')->with('meta')->andReturn($adapter);$run=(new AdDataSyncEngine($manager))->syncAccount($a,'manual','2026-11-01','2026-11-01');$this->assertSame('completed',$run->status);$this->assertSame(1,CanonicalCreative::where('connected_ad_account_id',$a->id)->count());$this->assertSame('shared-c',CanonicalCreative::where('connected_ad_account_id',$a->id)->first()->external_creative_id);$this->assertSame(1,CreativeObservation::where('sync_run_id',$run->id)->count());Http::assertSent(fn($r)=>str_contains($r->url(),'/campaigns')&&str_contains($r['fields'],'creative{id,name,object_type}'));}
}
